def longest_buildable(words: list[str]) -> str:
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = w                            # the whole word ends here
    best, stack = "", [root]
    while stack:
        node = stack.pop()
        for ch, child in node.items():
            if ch != "$" and "$" in child:       # step only onto nodes where a word ends
                word = child["$"]
                if len(word) > len(best) or (len(word) == len(best) and word < best):
                    best = word
                stack.append(child)
    return best
